struct vector3d {
    float x, y, z;
    vector3d operator-(const vector3d &v) const {
        vector3d r = { x-v.x, y-v.y, z-v.z };
        return r;
    }
    float length2() const { return x*x+y*y+z*z; }
};

struct po { char pad[0x30]; vector3d position; };
struct entity { char pad[0x50]; po *my_po; const vector3d &get_abs_position() const { return my_po->position; } };
struct board { char pad[0x50]; po *my_po; const vector3d &get_abs_position() const { return my_po->position; } };

struct SurferTrick {
    int trick_id, anim_id, board_anim_id, flags;
    char pad[0x48];
};
extern SurferTrick GTrickList[] __asm__("GTrickList");
__asm__(".equ GTrickList,0x00427CA8");

enum TRICKREGION { TREGION_FACE, TREGION_AIR, TREGION_TUBE };

class kellyslater_controller {
    char pad0[0xfc];
    TRICKREGION trickRegion;
    char pad1[0xd50];
    board *boardMember;
    char pad2[0xaa4];
    int completedTrick;
public:
    board *GetBoardMember() { return boardMember; }
    TRICKREGION GetTrickRegion() const { return trickRegion; }
    int GetCurrentTrick() const __asm__("GetCurrentTrick__22kellyslater_controller");
    int GetCompletedTrick() const { return completedTrick; }
};
__asm__(".equ GetCurrentTrick__22kellyslater_controller,0x0021E478");

class IconChallenge {
public:
    class Icon {
        entity *parentEnt;
    public:
        entity *GetEntity() { return parentEnt; }
    };
    class Task {
    public:
        enum TYPE {
            TYPE_AIR_FLIP, TYPE_AIR_GRAB, TYPE_AIR_SPIN,
            TYPE_AIR_POINTS_1000, TYPE_AIR_POINTS_2000, TYPE_AIR_POINTS_5000,
            TYPE_AIR_SPECIAL, TYPE_FACE_SPIN, TYPE_TUBE_TIME_10,
            TYPE_TUBE_TIME_15, TYPE_TUBE_TIME_30, TYPE_TUBE_TRICK,
            TYPE_NUM, TYPE_NONE
        };
    private:
        Icon *icon;
        bool completed;
        TYPE type;
        bool watchChain;
    public:
        void CheckForCompletion(kellyslater_controller *ksctrl);
    };
};

void IconChallenge::Task::CheckForCompletion(kellyslater_controller * ksctrl)
{
    entity *ent;
    float dist2;
    int currTrickIdx, compTrickIdx;

    if (!icon)
        return;
    ent = icon->GetEntity();
    if (!ent)
        return;
    dist2 = (ent->get_abs_position() - ksctrl->GetBoardMember()->get_abs_position()).length2();
    if (dist2 > 36.0f && ksctrl->GetTrickRegion() != TREGION_TUBE)
        return;

    currTrickIdx = ksctrl->GetCurrentTrick();
    compTrickIdx = ksctrl->GetCompletedTrick();

    switch (type)
    {
    case TYPE_NONE:
        return;
    case TYPE_AIR_FLIP:
        if ((currTrickIdx != -1) &&
            (GTrickList[currTrickIdx].flags & 0x8) &&
            ((GTrickList[currTrickIdx].flags & 0x10) == 0))
            watchChain = true;
        return;
    case TYPE_AIR_GRAB:
        if ((currTrickIdx != -1) &&
            (GTrickList[currTrickIdx].flags & 0x8) &&
            (GTrickList[currTrickIdx].flags & 0x10))
            watchChain = true;
        return;
    case TYPE_AIR_POINTS_1000:
    case TYPE_AIR_POINTS_2000:
    case TYPE_AIR_POINTS_5000:
        if (ksctrl->GetTrickRegion() == TREGION_AIR) watchChain = true;
        return;
    case TYPE_AIR_SPIN:
        if (ksctrl->GetTrickRegion() == TREGION_AIR) watchChain = true;
        return;
    case TYPE_AIR_SPECIAL:
        if ((currTrickIdx != -1) &&
            (GTrickList[currTrickIdx].flags & 0x80))
            watchChain = true;
        return;
    case TYPE_FACE_SPIN:
        if ((compTrickIdx != -1) &&
            (GTrickList[compTrickIdx].flags & 0x1) &&
            (compTrickIdx == 83))
            watchChain = true;
        return;
    case TYPE_TUBE_TIME_10:
        if (ksctrl->GetTrickRegion() == TREGION_TUBE) watchChain = true;
        return;
    case TYPE_TUBE_TRICK:
        if ((compTrickIdx != -1) &&
            (GTrickList[compTrickIdx].flags & 0x4) &&
            ((GTrickList[compTrickIdx].flags & 0x1000) == 0) &&
            ((GTrickList[compTrickIdx].flags & 0x2000) == 0))
            watchChain = true;
        return;
    default:
        return;
    };
}
